mapper.select:
SELECT f.*, s.name AS store_name, u.nickname AS handler_name
FROM ecom_feedback f
JOIN ecom_store s ON s.id = f.store_id
LEFT JOIN sys_user u ON u.id = f.handler_id

    AND f.store_id = #{q.storeId}
    AND f.platform = #{q.platform}
    AND f.rating <= #{q.maxRating}
    AND f.rating >= #{q.minRating}
    AND f.handle_status = #{q.handleStatus}
    AND f.feedback_date >= #{q.beginDate}
    AND f.feedback_date <= #{q.endDate}

        AND (f.comments LIKE CONCAT('%', #{q.keyword}, '%') OR f.rater LIKE CONCAT('%', #{q.keyword}, '%')
             OR f.platform_order_no LIKE CONCAT('%', #{q.keyword}, '%'))


ORDER BY CASE WHEN f.handle_status = 'PENDING' THEN 0 WHEN f.handle_status = 'PROCESSING' THEN 1 ELSE 2 END, f.feedback_date DESC, f.id DESC
